/bin/bash -lc "python - <<'PY'
import pathlib,re
for f in sorted(pathlib.Path('.').glob('*.txt')):
 t=f.read_text(); page='?'; hits=[]
 lines=t.splitlines()
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search(r'govern|constru|laws of|law of',l,re.I):
   hits.append((page,' '.join(lines[max(0,i-1):i+3])))
 print('\\nFILE',f.name[:-4])
 for p,s in hits: print('PAGE',p,s)
PY"

